Each MetaLab dataset is a curated meta-analysis of a phenomenon in early language or cognitive development. Click a dataset to explore it interactively; full data for every dataset can be downloaded on its page or from the versioned archive on Redivis.

registry = d3.json("slices/datasets.json")
domains = ([
  { id: "early_language", title: "Early language",
    desc: "How do children learn their native language?" },
  { id: "cognitive_development", title: "Cognitive development",
    desc: "What is the nature of children's understanding?" }
])
















html`${domains.map((dom) =&gt; html`
  &lt;h2&gt;${dom.title}&lt;/h2&gt;
  &lt;p&gt;${dom.desc}&lt;/p&gt;
  &lt;div class="dataset-grid"&gt;
    ${registry.filter((d) =&gt; d.domain === dom.id).map((d) =&gt; html`
      &lt;div class="dataset-card"&gt;
        &lt;h3&gt;&lt;a href="explorer.html?dataset=${encodeURIComponent(d.short_name)}"&gt;${d.name}&lt;/a&gt;&lt;/h3&gt;
        &lt;div class="card-desc"&gt;${d.short_desc ?? ""}&lt;/div&gt;
        &lt;div class="card-stats"&gt;${d.num_papers} papers · ${d.num_experiments} effect sizes · ${d.num_subjects.toLocaleString()} subjects&lt;/div&gt;
